import { ADJUSTMENT_KINDS } from "./adjustment-kinds.mjs";

// Returns what remains of the base price once the adjustment has been applied.
export function discountedSubtotal(basePrice, adjustment) {
  const multiplier =
    adjustment.kind === ADJUSTMENT_KINDS.PERCENT ? 1 - adjustment.value / 100 : 1;
  const flat = adjustment.kind === ADJUSTMENT_KINDS.FLAT ? adjustment.value : 0;
  return Math.max(0, basePrice * multiplier - flat);
}

export function reductionFor(basePrice, adjustment) {
  return basePrice - discountedSubtotal(basePrice, adjustment);
}

